head.script:
// https://inswave01.atlassian.net/browse/WAEA-1425

// 테스트 설명, 유효성 값 설정
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외
//    (Header/SubTotal/Footer Column 은 inputType=select 등 아이템 표시 기능이 없어 구분자 적용 여부를 관찰할 수 없음, 설정 영역 con 옵션 미생성)
scwin.tData = {
    "description" : "[column > P > delimiter]<br/>Column 과 아이템 리스트창에서 Label 과 Value 값이 함께 표시될때 값을 구분하는 구분자를 설정합니다.",
    "validation" : [
        "Column 의 inputType='select', 'checkcombobox', 'autoComplete' 이고, displayMode 또는 filterDisplayMode 속성이 'value delim label' 또는 'label delim value' 로 설정된 경우 동작합니다.",
        "구분자 텍스트 설정 시, Label 과 Value 값을 구분하는 구분자를 텍스트로 설정합니다.",
        "미설정 시, Tab('\\t')이 적용됩니다.",
        "inputType='checkcombobox' 인 Column 은 선택값이 여러 개이므로, 각 아이템의 Label 과 Value 를 구분자로 결합한 뒤 separator 속성값으로 이어 붙여 표시합니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_inputType.setValue("select");
    con_delimiter.setValue(":");
    con_displayMode.setValue("value delim label");
    con_filterDisplayMode.setValue("value delim label");
    con_separator.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 : 서울(SEL) / 부산(BSN) / 대구(DGU) / 인천(ICN)
//  - select / autoComplete 는 행별 첫번째 값만, checkcombobox 는 행별 값 전체를 separator 로 연결해 저장
scwin.rowPattern = [
    { "branch" : "본사", "city" : ["SEL"] },
    { "branch" : "영남지사", "city" : ["BSN", "DGU"] },
    { "branch" : "수도권지사", "city" : ["ICN", "SEL", "BSN"] }
];



// comp 생성
//  - branch : 비교용 text Column
//  - city   : 검증 대상 Body Column (inputType / displayMode / filterDisplayMode / delimiter / separator = con 값)
//             Header Column 에 useFilter=true 를 설정해 필터 창(CustomFilter) 의 항목 표시(filterDisplayMode) 를 확인
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cInputType = con_inputType.getValue();
    let cDisplayMode = con_displayMode.getValue();
    let cFilterDisplayMode = con_filterDisplayMode.getValue();
    let cDelimiter = con_delimiter.getValue();
    let cSeparator = con_separator.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] city Column 아이템 : 서울(SEL) / 부산(BSN) / 대구(DGU) / 인천(ICN), city Header 에 필터 버튼 표시\n[절차] city 셀 더블클릭으로 아이템 리스트창 열기 -> 아이템 리스트창 확인\n[절차] city Header 필터 버튼 클릭 -> 필터 창 값 입력란 목록 열기 -> 필터 창 닫기 -> 필터 항목 확인\n[확인] 결과창의 Tab 구분자는 [TAB] 으로 표기"', '', 'label1');

    // dataList 생성
    let dataSeparator = (cSeparator === '') ? ' ' : cSeparator;
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="branch" name="branch" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowPattern.map(function (row) {
        let city = (cInputType === "checkcombobox") ? row.city.join(dataSeparator) : row.city[0];
        return { "branch" : row.branch, "city" : city };
    }), false);

    // city Column 속성
    let attrCity = ' inputType="' + cInputType + '"';
    attrCity += (cDisplayMode === '') ? '' : ' displayMode="' + cDisplayMode + '"';
    attrCity += (cFilterDisplayMode === '') ? '' : ' filterDisplayMode="' + cFilterDisplayMode + '"';
    attrCity += (cDelimiter === '') ? '' : ' delimiter="' + cDelimiter + '"';
    attrCity += (cSeparator === '' || cInputType !== "checkcombobox") ? '' : ' separator="' + cSeparator + '"';

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>SEL</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>BSN</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>DGU</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>인천</w2:label><w2:value>ICN</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="branch"></w2:column>';
    strTarget += '<w2:column width="430" style="" inputType="text" id="column2" value="city (' + cInputType + ')" useFilter="true"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="branch" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="430" style="text-align:left;" id="city" value=""' + attrCity + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 1 ~ 4 : 재생성 직후 Column 셀 표시값
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("Column 셀 표시값 : " + scwin.getAllCellText());
    }, 100);
}



// Tab 구분자를 판별할 수 있도록 [TAB] 으로 치환하고 따옴표로 감싸 공백 구분자 확인
scwin.escapeText = function (str) {
    return "'" + String(str).split("\t").join("[TAB]") + "'";
}



scwin.getAllCellText = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_1']");
        arr.push(i + "행=" + (td ? scwin.escapeText(td.textContent) : "셀 없음"));
    }
    return arr.join(" / ");
}



// 한번 열었던 아이템 리스트창의 항목 텍스트 (리스트창을 닫아도 항목 DOM 은 유지되고, Target 재생성 시 함께 삭제됨)
//  - Column 편집기 : G_{gridID}___{selectbox|checkcombobox|autoComplete...}_city..._itemTable_{n}
//  - 필터 창 값 입력란 : {gridID}_item_{n}_autocomplete..._itemTable_{n}
scwin.getOpenItemText = function (idPrefix) {
    let tds = document.querySelectorAll("td[id^='" + idPrefix + "'][id*='_itemTable_']");
    let arr = [];
    tds.forEach(function (td) {
        if (/_itemTable_\d+$/.test(td.id)) {
            arr.push(scwin.escapeText(td.textContent));
        }
    });
    return arr;
}



// validation 1 ~ 4 : city 셀 편집 시 열린 아이템 리스트창 항목 텍스트
scwin.btn_checkItemList_onclick = function () {
    let arr = scwin.getOpenItemText("G_" + target1.id + "___");
    wf_body_bottom.getObj("scwin").setReturnValue("아이템 리스트창 : " + (arr.length ? arr.join(" / ") : "열린 아이템 리스트창 없음"));
}



// validation 1 ~ 3 : 필터 창 값 입력란의 아이템 리스트 항목 텍스트 (filterDisplayMode 적용 화면)
scwin.btn_checkFilterList_onclick = function () {
    let arr = scwin.getOpenItemText(target1.id + "_item_");
    wf_body_bottom.getObj("scwin").setReturnValue("필터 항목 : " + (arr.length ? arr.join(" / ") : "열린 필터 항목 리스트 없음"));
}
